import {createProjectFromBuiltin} from '../../src/project-import.js';import {preflightProject} from '../../src/analysis-preflight.js';import {createInputProvenance} from '../../src/input-provenance.js';
export function advancedStructuralProject(kind='thermalStress'){
 const p=createProjectFromBuiltin({source:{kind:'box',bounds:[0,0,0,10,10,40]}}),positions=p.meshes[0].positions,all=p.meshes[0].faceIds.map((_,i)=>i),face=(axis,v)=>all.filter(i=>[0,3,6].every(k=>Math.abs(positions[i*9+k+axis]-v)<1e-8));
 const condition=(type,value,direction,triangles)=>({type,value,direction,regions:[{mesh:0,triangles}]}),zero=axis=>[0,1,2].map(k=>Number(k===axis));
 p.study={kind:'structural',gravityEnabled:false};p.materialProperties={youngModulus:1e9,poissonRatio:0};
 if(kind==='thermalStress'){Object.assign(p.study,{thermalStress:true,temperature:80,referenceTemperature:20});p.materialProperties.expansion=1e-5;p.conditions=[condition('fixed',0,[1,0,0],all)];}
 else if(kind==='temperatureElastic'){p.study.materialTemperature=40;p.materialProperties={dependence:{elasticTemperatureTable:[{temperature:20,youngModulus:1e9,poissonRatio:0},{temperature:60,youngModulus:2e9,poissonRatio:0}],testConditions:'Synthetic uniform-temperature axial reference'}};p.conditions=[condition('fixed',0,[1,0,0],face(2,0)),condition('force',100,[0,0,1],face(2,40))];}
 else{Object.assign(p.study,{nonlinearLoadSteps:5,maxNewtonIterations:30});p.conditions=kind==='plasticity'?[[0,0,0],[1,0,0],[2,0,0],[2,40,.12]].map(([axis,at,value])=>condition('displacement',value,zero(axis),face(axis,at))):[condition('displacement',0,[1,0,0],all),condition('displacement',0,[0,1,0],all),condition('displacement',0,[0,0,1],face(2,0)),condition('displacement',8,[0,0,1],face(2,40))];p.materialProperties=kind==='plasticity'?{youngModulus:200e9,poissonRatio:.3,plasticity:{model:'j2-isotropic',yieldStress:250e6,hardeningModulus:1e9,testConditions:'Synthetic uniaxial small-strain bar'}}:{hyperelastic:{model:'neo-hookean-log',shearModulus:5e5,bulkModulus:2e6,testConditions:'Synthetic laterally constrained 20 percent stretch'}};}return p;
}
export function documentAdvancedStructural(p,mode='exploratory'){
 p.analysisIntent={mode};p.inputProvenance=createInputProvenance(preflightProject(p).requiredPointers.map(pointer=>({pointer,value:pointer.slice(1).split('/').reduce((value,key)=>value[key],p),source:{kind:mode==='exploratory'?'agent-proposal':'user-input'},rationale:'Explicit synthetic physical reference',applicability:'Existing limited CPU model,not measured calibration',status:mode==='exploratory'?'unconfirmed':'confirmed',assumption:mode==='exploratory'?'Synthetic unverified reference assumption':null})));return p;
}
export const contractByKind={thermalStress:'thermal-stress-isotropic-structure',temperatureElastic:'temperature-dependent-isotropic-structure',plasticity:'small-strain-j2-structure',hyperelastic:'finite-strain-neo-hookean-structure'};
